-- 研究池：航空航天 / 量子科技 未上市企业补录（2026-10-28）
-- aerospace 未上市 43 家、quantum 未上市 18 家（含前批 10 家，本文件为全量快照）
ON CONFLICT (name) DO UPDATE SET
  code=EXCLUDED.code, industry=EXCLUDED.industry, seg=EXCLUDED.seg,
  listed=EXCLUDED.listed, round=EXCLUDED.round, valuation=EXCLUDED.valuation,
  rev=EXCLUDED.rev, data=EXCLUDED.data, updated_at=now();

-- 跨行业归属修正：三家按主营收入归回航空航天
UPDATE public.research_companies SET industry='aerospace', seg='space-payload', updated_at=now()
 WHERE name IN ('天奥电子','国光电气');
UPDATE public.research_companies SET industry='aerospace', seg='aero-material', updated_at=now()
 WHERE name='西部超导';
